import Vue from 'vue';
import { OverlaysEventEmitter } from '../../event-emitter';
import { IDemoMessagingData, MessageState } from '../../types';

export default Vue.component('demo-messaging', {
    name: 'DemoMessaging',
    props: {
        strings: { type: Object, required: false },
        deviceType: { type: String, required: true },
        viewHeight: { type: Number, required: true },
        isDemoMode: { type: Function, required: true },
        onOutOfPlays: { type: Function, required: true },
        returnToLobby: { type: Function, required: true }
    },
    data(): IDemoMessagingData {
        return {
            isVisible: false,
            inSettings: false,
            message: this.strings?.welcome.message ?? 'message',
            button: this.strings?.welcome.button ?? 'button',
            title: this.strings?.title ?? 'title',
            messageState: 'Welcome',
        };
    },
    mounted(): void {
        this.onOutOfPlays(this.outOfPlays, this);

        OverlaysEventEmitter.on('enterDemoMode', () => this.showOverlay('Welcome'));
        OverlaysEventEmitter.on('leaveDemoMode', () => this.showOverlay('Leave'));
        OverlaysEventEmitter.on('outOfPlays', () => this.showOverlay('OutOfPlays'));
    },
    methods: {
        outOfPlays(): void {
            this.$forceUpdate();
            this.isVisible = true;
        },
        onClick(): void {
            this.hideOverlay();
        },
        hideOverlay(): void {
            this.isVisible = false;
        },
        redirectToLobby(): void {
            this.hideOverlay();
            this.returnToLobby();
        },
        onSettingsVisibility(isVisible: boolean): void {
            this.inSettings = isVisible;
        },
        showOverlay(state: MessageState): void {
            this.messageState = state;

            switch (this.messageState) {
                case 'Leave':
                    this.title = this.strings.inDemoTitle;
                    this.message = this.strings?.leave.message;
                    this.button = this.strings?.leave.button;
                    break;
                case 'OutOfPlays':
                    this.title = this.strings?.title;
                    this.message = this.strings?.outOfPlays.message;
                    this.button = this.strings?.outOfPlays.button;
                    break;
                case 'Welcome':
                default:
                    this.title = this.strings?.title;
                    this.message = this.strings?.welcome.message;
                    this.button = this.strings?.welcome.button;
                    break;
            }

            this.isVisible = true;
        }
    }
});